  const summary=document.createElement('fieldset'); summary.id='reservationLiveSummary'; summary.className='reservation-live-summary'; summary.innerHTML='<legend>Resumen antes de guardar</legend><div class="reservation-summary-grid"><span>Noches <b id="liveNights">—</b></span><span>Alojamiento <b id="liveLodgingTotal">$0,00</b></span><span>Pagado <b id="liveLodgingPaid">$0,00</b></span><span>Saldo alojamiento <b id="liveLodgingPending">$0,00</b></span><span>Consumos <b id="liveConsumptionTotal">$0,00</b></span><span>Consumos pendientes <b id="liveConsumptionPending">$0,00</b></span><strong>Total pendiente <b id="liveTotalPending">$0,00</b></strong></div>';
