$('prevWeek').onclick=()=>{calendarDate.setDate(calendarDate.getDate()-7);$('calendarDatePicker').value=isoDate(calendarDate);loadCalendar();}; $('nextWeek').onclick=()=>{calendarDate.setDate(calendarDate.getDate()+7);$('calendarDatePicker').value=isoDate(calendarDate);loadCalendar();}; $('todayWeek').onclick=()=>{calendarDate=new Date();$('calendarDatePicker').value=isoDate(calendarDate);loadCalendar();};
$('newReservation').onclick=()=>{resetReservation();$('consumptionDate').value=isoDate(new Date());$('chargeDate').value='';$('consumptionPaid').checked=false;syncConsumptionPaymentFields();$('reservationDialog').showModal();};
$('cancelReservation').onclick=()=>{if(reservationDirty&&!window.confirm('Hay cambios sin guardar. ¿Cerrar igualmente?'))return;reservationDirty=false;$('reservationDialog').close();};
$('consumptionPaid').onchange=syncConsumptionPaymentFields;
$('addConsumption').onclick=()=>{const description=$('consumptionType').value,amount=Number($('consumptionAmount').value),consumedOn=$('consumptionDate').value,paid=$('consumptionPaid').checked,chargedOn=paid?$('chargeDate').value:null;if(!amount||!consumedOn)return flash('Completá tipo, monto y fecha del consumo',true);if(paid&&!chargedOn)return flash('Elegí la fecha de cobro del consumo pagado',true);formConsumptions.push({description,amount,consumedOn,chargedOn,method:$('consumptionMethod').value});reservationDirty=true;renderConsumptions();$('consumptionAmount').value='';$('consumptionPaid').checked=false;syncConsumptionPaymentFields();};
$('consumptionList').onclick=e=>{const b=e.target.closest('[data-remove-consumption]');if(b){formConsumptions.splice(Number(b.dataset.removeConsumption),1);reservationDirty=true;renderConsumptions();return;}const pay=e.target.closest('[data-pay-consumption]');if(pay)openPaymentDialog(pay.dataset.payConsumption);};
$('paymentForm').onsubmit=async e=>{e.preventDefault();$('paymentError').textContent='';try{if(pendingLodgingPaymentId){const amount=Number($('paymentAmount').value);if(!amount){$('paymentError').textContent='Ingresá un importe válido';return;}const id=pendingLodgingPaymentId;await api('/reservations/'+id+'/payments',{method:'POST',body:JSON.stringify({amount,method:$('paymentMethodDialog').value,notes:''})});closePaymentDialog();await loadReservations();await dashboard();const found=reservations.find(r=>r.id===id);if(found)editReservation(found);flash('Pago cargado en caja');return;}if(!pendingPaymentConsumptionId)return;const id=$('reservationId').value;await api('/consumptions/'+pendingPaymentConsumptionId+'/pay',{method:'PATCH',body:JSON.stringify({paidOn:$('paymentDate').value,method:$('paymentMethodDialog').value})});closePaymentDialog();await loadConsumptions(id);await loadBalance(id);await dashboard();flash('Consumo cobrado y cargado en caja');}catch(x){$('paymentError').textContent=x.message;}};
$('cancelPayment').onclick=closePaymentDialog; $('cancelPaymentBottom').onclick=closePaymentDialog;
$('reservationForm').onsubmit=async e=>{e.preventDefault();$('reservationError').textContent='';if(!e.target.reportValidity())return;try{const id=$('reservationId').value;const saved=await api(id?'/reservations/'+id:'/reservations',{method:id?'PATCH':'POST',body:JSON.stringify(reservationBody())});if(id){for(const c of formConsumptions.filter(x=>!x.id))await api('/reservations/'+saved.id+'/consumptions',{method:'POST',body:JSON.stringify(c)});}reservationDirty=false;$('reservationDialog').close();await loadReservations();dashboard();flash(id?'Reserva actualizada':'Reserva creada');}catch(x){$('reservationError').textContent=x.message;}};
$('openCash').onclick=async()=>{const raw=$('cashOpening').value.trim(),opening=Number(raw);$('cashOpenError').textContent='';if(!raw||!Number.isFinite(opening)||opening<0)return $('cashOpenError').textContent='Ingresá un saldo inicial válido';try{await api('/cash/'+$('cashDate').value+'/open',{method:'POST',body:JSON.stringify({openingBalance:opening})});await loadCash();flash('Caja abierta');}catch(x){$('cashOpenError').textContent=x.message;}}; $('cashForm').onsubmit=async e=>{e.preventDefault();try{await api('/cash/movements',{method:'POST',body:JSON.stringify({kind:$('cashKind').value,amount:$('cashAmount').value,method:$('cashMethod').value,description:$('cashDescription').value,movementDate:$('cashDate').value})});e.target.reset();loadCash();}catch(x){flash(x.message,true);}}; $('cashDate').onchange=loadCash; $('closeCash').onclick=()=>{$('cashCloseError').textContent='';$('countedBalance').value='';$('cashCloseDialog').showModal();}; $('cancelCashClose').onclick=()=>$('cashCloseDialog').close(); $('cancelCashCloseBottom').onclick=()=>$('cashCloseDialog').close(); $('cashCloseForm').onsubmit=async e=>{e.preventDefault();$('cashCloseError').textContent='';try{await api('/cash/'+$('cashDate').value+'/close',{method:'POST',body:JSON.stringify({countedBalance:$('countedBalance').value})});$('cashCloseDialog').close();await loadCash();flash('Caja cerrada');}catch(x){$('cashCloseError').textContent=x.message;}};
$('newRoom').onclick=()=>{$('roomTitle').textContent='Nueva habitación';$('roomForm').reset();$('roomIdEdit').value='';renderRooms();$('roomDialog').showModal();}; $('cancelRoom').onclick=()=>$('roomDialog').close(); $('roomForm').onsubmit=async e=>{e.preventDefault();try{const id=$('roomIdEdit').value;const body={number:$('roomNumber').value,floor:$('roomFloor').value,categoryId:$('roomCategory').value || null,capacity:$('roomCapacity').value,basePrice:$('roomPrice').value,status:$('roomStatus').value};await api(id?'/rooms/'+id:'/rooms',{method:id?'PATCH':'POST',body:JSON.stringify(body)});$('roomDialog').close();rooms=await api('/rooms');renderRooms();flash(id?'Habitación actualizada':'Habitación creada');}catch(x){flash(x.message,true);}};
$('newCategory').onclick=()=>{$('categoryTitle').textContent='Nueva categoría';$('categoryForm').reset();$('categoryIdEdit').value='';$('categoryError').textContent='';$('categoryDialog').showModal();}; $('cancelCategory').onclick=()=>$('categoryDialog').close(); $('cancelCategoryBottom').onclick=()=>$('categoryDialog').close(); $('categoryForm').onsubmit=async e=>{e.preventDefault();$('categoryError').textContent='';try{const id=$('categoryIdEdit').value;const body={name:$('categoryName').value,description:$('categoryDescription').value};await api(id?'/room-categories/'+id:'/room-categories',{method:id?'PATCH':'POST',body:JSON.stringify(body)});roomCategories=await api('/room-categories');$('categoryDialog').close();renderRooms();flash(id?'Categoría actualizada':'Categoría creada');}catch(x){$('categoryError').textContent=x.message;}};
$('newProduct').onclick=()=>{$('productTitle').textContent='Nuevo producto';$('productForm').reset();$('productIdEdit').value='';$('productDialog').showModal();}; $('cancelProduct').onclick=()=>$('productDialog').close(); $('productForm').onsubmit=async e=>{e.preventDefault();try{const id=$('productIdEdit').value;const body={name:$('productName').value,category:$('productCategory').value,unit:$('productUnit').value,minimumStock:$('productMinimum').value,cost:$('productCost').value,supplier:$('productSupplier').value};await api(id?'/products/'+id:'/products',{method:id?'PATCH':'POST',body:JSON.stringify(body)});$('productDialog').close();await loadProducts();flash(id?'Producto actualizado':'Producto agregado; ya está disponible en consumos extra');}catch(x){flash(x.message,true);}};
$('cancelHotelSettings').onclick=()=>$('hotelSettingsDialog').close(); $('cancelHotelSettingsBottom').onclick=()=>$('hotelSettingsDialog').close(); $('hotelSettingsForm').onsubmit=async e=>{e.preventDefault();$('hotelSettingsError').textContent='';try{hotelSettings=await api('/settings',{method:'PATCH',body:JSON.stringify({hotelName:$('hotelNameInput').value})});applyHotelName();$('hotelSettingsDialog').close();flash('Nombre actualizado');}catch(x){$('hotelSettingsError').textContent=x.message;}};
$('downloadExport').onclick=async()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(await api('/export'),null,2)],{type:'application/json'}));a.download='hotel-backup-'+isoDate(new Date())+'.json';a.click();}; initDatePickers(); boot(); window.addEventListener('unhandledrejection',e=>{e.preventDefault();flash(e.reason?.message||'No se pudo completar la operación',true);});
